const CATALOG_KINDS=['Todas','Magias','Talentos','Classes','Subclasses','Características','Espécies','Antecedentes','Equipamento','Livro completo'];
const AB_EN=['Strength','Dexterity','Constitution','Intelligence','Wisdom','Charisma'];
const SK_EN=['Acrobatics','Arcana','Athletics','Performance','Deception','Stealth','History','Intimidation','Insight','Investigation','Animal Handling','Medicine','Nature','Perception','Persuasion','Sleight of Hand','Religion','Survival'];
let catalogState={kind:'Todas',query:'',relevant:true,page:0},builderStep=0;
function normBook(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();}
function selections(){const x=c();if(!x.bookChoices)x.bookChoices={species:'',background:'',subclasses:{},feats:[],spells:[],items:[],boostA:0,boostB:1,boostMode:'2+1',appliedBoosts:Array(6).fill(0)};x.bookChoices.subclasses=x.bookChoices.subclasses||{};return x.bookChoices;}
function getBook(id){return BOOK.entries.find(e=>e.id===id)}
function currentSpellMax(cls){const p=c().classes.find(p=>p.name===cls);if(!p)return 0;const n=p.level;if(['Paladino','Patrulheiro'].includes(cls))return Math.ceil(n/4);if(['Guerreiro','Ladino'].includes(cls))return p.third&&n>=3?Math.ceil(Math.ceil(n/3)/2):0;return ['Bardo','Bruxo','Clérigo','Druida','Feiticeiro','Mago'].includes(cls)?Math.min(cls==='Bruxo'?5:9,Math.ceil(n/2)):0;}
function relevantBook(e){const x=c(),classes=x.classes.map(p=>p.name);if(e.kind==='Magias')return e.classes.some(cls=>classes.includes(cls)&&e.level<=currentSpellMax(cls))||x.classes.some(p=>p.third&&p.level>=3&&e.classes.includes('Mago')&&e.level<=currentSpellMax(p.name));if(e.classes&&!e.classes.some(cls=>classes.includes(cls)))return false;if(e.kind==='Características'){const p=x.classes.find(p=>e.classes.includes(p.name));return p&&p.level>=e.minLevel;}if(e.kind==='Subclasses')return x.classes.some(p=>e.classes.includes(p.name)&&p.level>=3);if(e.kind==='Talentos')return x.level>=e.minLevel;return true;}
function catalogView(){return `<section class="card"><h2>Catálogo de regras · Edição 5.5</h2><div class="row"><label>Categoria<select aria-label="Categoria do catálogo" onchange="catalogState.kind=this.value;catalogState.page=0;render()">${CATALOG_KINDS.map(k=>`<option ${k===catalogState.kind?'selected':''}>${k}</option>`).join('')}</select></label><label class="catalog-check"><input type="checkbox" ${catalogState.relevant?'checked':''} onchange="catalogState.relevant=this.checked;catalogState.page=0;renderCatalogResults()"> Adequado à ficha</label></div><input type="search" id="catalog-search" aria-label="Pesquisar regras" placeholder="Nome, termo ou regra em inglês…" value="${esc(catalogState.query)}" oninput="catalogState.query=this.value;catalogState.page=0;renderCatalogResults()"><p class="muted">O filtro considera classes, níveis e círculos de magia; não valida todos os pré-requisitos, listas adicionais de subclasses ou limites de preparação.</p><div id="catalog-results">${catalogResultsHtml()}</div></section>`;}
function catalogItems(){let items=catalogState.kind==='Livro completo'?BOOK.pages.map(p=>({id:'page-'+p.page,kind:p.category,name:p.category+' · PDF '+p.page,page:p.page,text:p.text})):BOOK.entries.filter(e=>catalogState.kind==='Todas'||e.kind===catalogState.kind);const q=normBook(catalogState.query);return items.filter(e=>(catalogState.kind==='Livro completo'||!catalogState.relevant||relevantBook(e))&&(!q||normBook(e.name+' '+e.text+' '+spellSearch434(e)).includes(q)));}
function catalogResultsHtml(){const items=catalogItems(),start=catalogState.page*20;return `<div class="row"><p>${items.length} resultados</p><span class="muted">${items.length?start+1:0}–${Math.min(items.length,start+20)}</span></div>${items.slice(start,start+20).map(e=>`<article class="catalog-result"><div class="catalog-meta427"><span class="eyebrow">${esc(e.kind)}${e.level!==undefined?' · '+(e.level?'Círculo '+e.level:'Truque'):''}</span><small>${e.source?esc(e.source):'PDF p. '+e.page}</small></div><div class="catalog-name427"><h3>${esc(e.name)}</h3><button class="catalog-help426" aria-label="Ler detalhes" title="Ler detalhes" onclick="openBookEntry('${e.id}')">?</button>${['Magias','Talentos','Equipamento'].includes(e.kind)?`<button class="catalog-select428" aria-label="${isBookSelected(e)?'Remover da ficha':'Selecionar'}" title="${isBookSelected(e)?'Remover da ficha':'Selecionar'}" aria-pressed="${isBookSelected(e)}" onclick="toggleBookChoice('${e.id}')">${isBookSelected(e)?'✓':'+'}</button>`:''}</div>${e.classes?.length?'<small>'+esc(e.classes.join(', '))+'</small>':''}</article>`).join('')}<div class="actions"><button ${catalogState.page===0?'disabled':''} onclick="catalogState.page--;renderCatalogResults()">Anterior</button><button ${(start+20)>=items.length?'disabled':''} onclick="catalogState.page++;renderCatalogResults()">Próxima</button></div>`;}

function renderCatalogResults(){document.querySelector('#catalog-results').innerHTML=catalogResultsHtml();}
function openBookEntry(id){let e=id.startsWith('page-')?{name:'Página do livro',page:Number(id.slice(5)),text:''}:getBook(id);if(!e)return;document.querySelector('#book-detail-title').textContent=e.name;document.querySelector('#book-detail-meta').textContent='Fonte: PDF p. '+e.page+' · texto OCR original em inglês';document.querySelector('#book-detail-text').textContent=e.text||BOOK.pages.find(p=>p.page===e.page)?.text||'Esta página contém somente imagem.';document.querySelector('#book-detail-page').textContent=BOOK.pages.find(p=>p.page===e.page)?.layout||'';document.querySelector('#book-page-number').value=e.page;document.querySelector('#book-detail').showModal();}
function loadBookPage(){const n=Math.max(1,Math.min(BOOK.sourcePages,Number(document.querySelector('#book-page-number').value)||1)),p=BOOK.pages.find(p=>p.page===n);document.querySelector('#book-detail-meta').textContent='PDF p. '+n+' · texto OCR';document.querySelector('#book-detail-text').textContent=p?.text||'Sem camada de texto nesta página.';document.querySelector('#book-detail-page').textContent=p?.layout||'';}
function isBookSelected(e){const s=selections(),key=e.kind==='Magias'?'spells':e.kind==='Talentos'?'feats':'items';return s[key].includes(e.id);}
function toggleBookChoice(id){const e=getBook(id);if(!e)return;const s=selections(),key=e.kind==='Magias'?'spells':e.kind==='Talentos'?'feats':'items';if(s[key].includes(id))s[key]=s[key].filter(x=>x!==id);else{s[key].push(id);if(e.kind==='Magias'&&!relevantBook(e))toast('Selecionada manualmente: confira acesso e círculo na mesa.');}if(e.name==='Tough'){c().calc.tough=s.feats.some(id=>getBook(id)?.name==='Tough')||Boolean(s.originTough);}recalc(c());save();render();}
function bset(key,value){const s=selections();s[key]=value;if(key==='background'){const allowed=(getBook(value)?.abilities||[]).map(n=>AB_EN.indexOf(n));s.boostA=allowed[0];s.boostB=allowed[1];}save();render();}
function optsKind(kind,value){return `<option value="">Escolher…</option>`+BOOK.entries.filter(e=>e.kind===kind).map(e=>`<option value="${e.id}" ${value===e.id?'selected':''}>${esc(e.name)}</option>`).join('');}
function selectedRule(id){const e=getBook(id);return e?`<p class="muted">${esc(e.english||e.name)} · PDF p. ${e.page}</p><button class="rule-help" aria-label="Ler regra completa" title="Ler regra completa" onclick="openBookEntry('${e.id}')">?</button>`:'';}
function builderView(){const s=selections(),x=c(),steps=['Classe','Origem','Atributos','Talentos','Magias','Equipamento','Revisão'];return `<section class="card"><h2>Criação guiada</h2><p class="muted">Escolhas salvas nesta ficha. Leia as regras de referência e aplique a origem explicitamente. Opções de linhagem, proficiências de classe, aumentos de atributos por nível e efeitos especiais ainda precisam de revisão manual.</p><div class="builder-steps">${steps.map((n,i)=>`<button class="${builderStep===i?'primary':''}" onclick="builderStep=${i};render()">${i+1}. ${n}</button>`).join('')}</div>${builderBody()}<div class="actions"><button ${builderStep===0?'disabled':''} onclick="builderStep--;render()">Anterior</button><button ${builderStep===6?'disabled':''} onclick="builderStep++;render()">Próxima etapa</button></div></section>`;}
function builderBody(){const s=selections(),x=c();if(builderStep===0)return `<h3>Classes e subclasses</h3>${x.classes.map((p,i)=>{const e=BOOK.entries.find(e=>e.kind==='Classes'&&e.name===p.name);return `<div class="card"><div class="row"><label>Classe<select onchange="changeClass(${i},'name',this.value)">${CLASSES.map(n=>`<option ${n===p.name?'selected':''}>${n}</option>`).join('')}</select></label><label>Níveis<input type="number" min="1" max="20" value="${p.level}" onchange="changeClass(${i},'level',this.value)"></label></div>${e?`<button onclick="openBookEntry('${e.id}')">Regras de ${p.name} e progressão</button>`:''}<label>Subclasse (disponível no nível 3)<select ${p.level<3?'disabled':''} onchange="chooseSubclass('${p.name}',this.value)"><option value="">Escolher…</option>${BOOK.entries.filter(e=>e.kind==='Subclasses'&&e.classes.includes(p.name)).map(e=>`<option value="${e.id}" ${s.subclasses[p.name]===e.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label>${selectedRule(s.subclasses[p.name])}${progressionTable(p,i)}</div>`}).join('')}<button onclick="addClass()">＋ Adicionar multiclasse</button>`;
if(builderStep===1)return `<h3>Espécie e antecedente</h3><label>Espécie<select onchange="bset('species',this.value)">${optsKind('Espécies',s.species)}</select></label>${selectedRule(s.species)}<label>Antecedente<select onchange="bset('background',this.value)">${optsKind('Antecedentes',s.background)}</select></label>${selectedRule(s.background)}<p class="muted">Aplicar origem atualiza espécie, deslocamento, antecedente, perícias do antecedente e Robusto quando concedido. Heranças e escolhas adicionais continuam manuais.</p><button class="primary" onclick="applyBookOrigin()">Aplicar origem à ficha</button>`;
if(builderStep===2){const bg=getBook(s.background),allowed=bg?.abilities?.map(n=>AB_EN.indexOf(n))||[];return `<h3>Atributos e bônus do antecedente</h3><p class="muted">Edite os valores antes dos bônus. Constituição recalcula os PV. Use Aplicar bônus para confirmar; reaplicar substitui o bônus anterior, sem somar duas vezes.</p><div class="attribute-builder">${ATTR.map((a,i)=>`<label>${a}<input type="number" min="1" max="30" value="${x.attrs[i]-(s.appliedBoosts?.[i]||0)}" onchange="setBaseBookAttr(${i},Number(this.value))"></label>`).join('')}</div><button onclick="useStandardArray()">Usar conjunto padrão 15, 14, 13, 12, 10, 8</button><p>Bônus permitidos: ${allowed.map(i=>ATTR[i]).join(', ')||'escolha um antecedente primeiro'}.</p><label>Distribuição<select onchange="bset('boostMode',this.value)"><option ${s.boostMode==='2+1'?'selected':''}>2+1</option><option ${s.boostMode==='1+1+1'?'selected':''}>1+1+1</option></select></label>${s.boostMode==='2+1'?`<div class="row"><label>+2 em<select onchange="bset('boostA',Number(this.value))">${allowed.map(i=>`<option value="${i}" ${s.boostA===i?'selected':''}>${ATTR[i]}</option>`).join('')}</select></label><label>+1 em<select onchange="bset('boostB',Number(this.value))">${allowed.map(i=>`<option value="${i}" ${s.boostB===i?'selected':''}>${ATTR[i]}</option>`).join('')}</select></label></div>`:''}<button class="primary" onclick="applyBookBoosts()">Aplicar bônus do antecedente</button>`;}
if(builderStep===3)return `<h3>Talentos</h3><p>Talento de origem: <b>${esc(s.originFeat||getBook(s.background)?.feat||'Escolha o antecedente')}</b></p><p class="muted">Os pré-requisitos completos aparecem nos detalhes. O filtro considera apenas nível. Outros efeitos, além de Robusto, exigem ajustes manuais.</p>${choiceTable('Talentos',s.feats)}`;
if(builderStep===4)return `<h3>Magias e truques</h3><p class="muted">Filtrado pelas classes e círculos individuais. Subclasses e talentos podem conceder acesso adicional: consulte também Todas no Catálogo. A quantidade de magias conhecidas/preparadas precisa ser conferida na tabela da classe.</p>${choiceTable('Magias',s.spells)}`;
if(builderStep===5)return `<h3>Equipamento</h3><p class="muted">Selecione itens para sua lista. Preço, peso e propriedades vêm da linha OCR; quantidades, pacotes iniciais e ataques precisam ser conferidos.</p>${choiceTable('Equipamento',s.items)}`;
return `<h3>Revisão</h3><table><tbody><tr><th>Nível total</th><td>${x.level}</td></tr><tr><th>Classes</th><td>${esc(x.classes.map(p=>p.name+' '+p.level).join(' / '))}</td></tr><tr><th>Espécie</th><td>${esc(x.species||'Pendente')}</td></tr><tr><th>Antecedente</th><td>${esc(x.background||'Pendente')}</td></tr><tr><th>PV máximos</th><td>${x.maxhp}</td></tr><tr><th>Talentos escolhidos</th><td>${s.feats.length}</td></tr><tr><th>Magias escolhidas</th><td>${s.spells.length}</td></tr><tr><th>Itens escolhidos</th><td>${s.items.length}</td></tr></tbody></table><p class="muted">Confira as proficiências de classe, equipamentos, pré-requisitos e escolhas de linhagem. O catálogo contém o texto integral extraído, mas o construtor não aplica automaticamente todos os efeitos do livro.</p>`;}
function choiceTable(kind,ids){const entries=BOOK.entries.filter(e=>e.kind===kind&&(kind==='Equipamento'||relevantBook(e)));return `<input type="search" aria-label="Filtrar ${kind}" placeholder="Filtrar pelo nome em inglês…" oninput="filterBuilderRows(this)"><div class="builder-options">${entries.map(e=>`<div class="builder-option" data-book-name="${esc(normBook(e.name+' '+spellName434(e)))}"><label><input type="checkbox" ${ids.includes(e.id)?'checked':''} onchange="toggleBookChoice('${e.id}')"><span>${esc(e.name)}${e.level!==undefined?' · '+(e.level?'círculo '+e.level:'truque'):''}</span></label><button onclick="openBookEntry('${e.id}')">Regra</button></div>`).join('')}</div>`;}
function filterBuilderRows(input){input.nextElementSibling.querySelectorAll('[data-book-name]').forEach(row=>row.hidden=!row.dataset.bookName.includes(normBook(input.value)));}
function chooseSubclass(cls,id){const s=selections(),e=getBook(id);s.subclasses[cls]=id;if(cls==='Feiticeiro')c().calc.draconicHP=e?.name==='Draconic Sorcery';c().subclass=Object.values(s.subclasses).map(id=>getBook(id)?.name).filter(Boolean).join(' / ');const p=c().classes.find(p=>p.name===cls);if(['Guerreiro','Ladino'].includes(cls))p.third=Boolean(e&&['Eldritch Knight','Arcane Trickster'].includes(e.name));recalc(c());save();render();}
function applyBookOrigin(){const s=selections(),x=c(),species=getBook(s.species),bg=getBook(s.background);if(!species||!bg)return toast('Escolha espécie e antecedente.');x.species=species.name;x.background=bg.name;x.speed=species.speed;const newPer=0;x.calc.dwarfHP=species.name==='Anão';x.calc.perLevel=Number(x.calc.perLevel||0)-(s.appliedSpeciesPV||0)+newPer;s.appliedSpeciesPV=newPer;if(s.originTough&&!bg.feat.includes('Tough')){x.calc.tough=s.previousTough||s.feats.some(id=>getBook(id)?.name==='Tough');s.originTough=false;}if(bg.feat.includes('Tough')&&!s.originTough){s.previousTough=x.calc.tough;x.calc.tough=true;s.originTough=true;}for(const old of s.originSkills||[]){if((x.skills[old.i]||0)===1)x.skills[old.i]=old.before;}s.originSkills=[];SK_EN.forEach((en,i)=>{if(bg.skills.includes(en)){s.originSkills.push({i,before:x.skills[i]||0});x.skills[i]=Math.max(1,x.skills[i]||0);}});s.originFeat=bg.feat;const allowed=bg.abilities.map(n=>AB_EN.indexOf(n));if(!allowed.includes(s.boostA))s.boostA=allowed[0];if(!allowed.includes(s.boostB)||s.boostB===s.boostA)s.boostB=allowed.find(i=>i!==s.boostA);recalc(x);save();render();toast('Origem aplicada. Confira ferramentas, idiomas e traços na referência.');}
function setBaseBookAttr(i,value){c().attrs[i]=Math.max(1,Math.min(30,value))+(selections().appliedBoosts[i]||0);recalc(c());save();render();}
function useStandardArray(){c().attrs=[15,14,13,12,10,8].map((n,i)=>n+(selections().appliedBoosts[i]||0));recalc(c());save();render();}
function applyBookBoosts(){const s=selections(),bg=getBook(s.background);if(!bg)return toast('Escolha um antecedente.');const allowed=bg.abilities.map(n=>AB_EN.indexOf(n)),boosts=Array(6).fill(0);if(s.boostMode==='1+1+1')allowed.forEach(i=>boosts[i]=1);else{if(s.boostA===s.boostB||!allowed.includes(s.boostA)||!allowed.includes(s.boostB))return toast('Escolha dois atributos diferentes permitidos.');boosts[s.boostA]=2;boosts[s.boostB]=1;}const attrs=c().attrs.map((n,i)=>n-(s.appliedBoosts[i]||0)+boosts[i]);if(attrs.some(n=>n>20))return toast('Bônus de antecedente não pode ultrapassar 20.');c().attrs=attrs;s.appliedBoosts=boosts;recalc(c());save();render();toast('Bônus aplicados sem acumulação.');}
function bookSelectionsPanel(kind){const s=selections(),key=kind==='Magias'?'spells':kind==='Talentos'?'feats':'items',chosen=s[key].map(getBook).filter(Boolean);return `<section class="card"><h3>${kind} do catálogo</h3>${chosen.length?chosen.map(e=>`<div class="row"><span>${esc(e.name)}</span><button onclick="openBookEntry('${e.id}')">Detalhes</button></div>`).join(''):'<p class="muted">Use Criação guiada ou Catálogo para selecionar.</p>'}</section>`;}
const magicBeforeBook=magic;magic=function(){return bookSelectionsPanel('Magias')+magicBeforeBook();};const gearBeforeBook=gear;gear=function(){return bookSelectionsPanel('Equipamento')+gearBeforeBook();};
const combatBeforeBook=combat;combat=function(){const features=BOOK.entries.filter(e=>e.kind==='Características'&&relevantBook(e));return bookSelectionsPanel('Talentos')+`<section class="card"><h3>Características por nível</h3><p class="muted">Referências da classe conforme o nível; não aplicam efeitos automaticamente. Consulte a subclasse escolhida na criação guiada.</p>${features.map(e=>`<div class="row"><span>${esc(e.classes[0])} ${e.minLevel} · ${esc(e.name)}</span><button onclick="openBookEntry('${e.id}')">Regra</button></div>`).join('')}</section>`+combatBeforeBook();};

function progressionTable(p,index){const x=c();return `<details class="progression-table"><summary>Tabela de progressão · escolher nível</summary><div class="progress-scroll"><table><thead><tr><th>Nível</th><th>Prof.</th><th>PV*</th><th>Espaços</th></tr></thead><tbody>${Array.from({length:20},(_,j)=>{const level=j+1,temp={...x,level,classes:[{...p,level}]},slots=casterInfo(temp),hp=hpValue(temp);return `<tr class="${p.level===level?'current-level':''}"><td><button onclick="changeClass(${index},'level',${level})">${level}${p.level===level?' ✓':''}</button></td><td>+${2+Math.floor((level-1)/4)}</td><td>${hp}</td><td>${slots.pact.count?slots.pact.count+' de '+slots.pact.level+'º · Pacto':slots.slots.map((n,i)=>n?(i+1)+'º: '+n:'').filter(Boolean).join(' · ')||'—'}</td></tr>`}).join('')}</tbody></table></div><p class="muted">*PV de personagem somente nesta classe, usando sua Constituição, valor fixo e ajustes configurados. A tabela não soma outras classes; o total da ficha respeita a multiclasse.</p></details>`;}
